"}. Si tu ne trouves pas de valeur fiable sur une page, réponds {\"taux_pour_1\": null}. N'utilise jamais ta mémoire.`, { tools: [webTool()], modelTier: \"quick\" });\n    const v = Number(data && data.taux_pour_1);\n    if (!Number.isFinite(v) || v <= 0) { toast(\"Taux non trouvé. Saisis ton taux réel.\"); return; }\n    await saveRate(cur, v, String(data.date || today()).slice(0, 10), String(data.source || \"recherche web\").slice(0, 200));\n    applyStoredRate(true); toast(\"Taux mis à jour. Vérifie-le avant de décider.\");\n  } catch (e) { console.error(e); toast(sampleMsg(e) || \"Recherche arrêtée.\"); }\n  finally { btn.disabled = false; btn.textContent = old; setStatus(\"\"); }\n}\nfunction renderStats() {\n  const box = $(\"#stats-out\"); box.textContent = \"\";\n  const sel = $(\"#c-model\");\n  if (S.statsErr) { box.append(h(\"div\", { class: \"note warn\", text: S.statsErr })); return; }\n  if (!S.stats) { box.append(h(\"div\", { class: \"small\", text: cap.soft ? \"Charge tes chiffres pour comparer avec tes achats passés.\" : \"Disponible quand le connecteur Cloudflare est relié à Claude.\" })); return; }\n  if (!sel.options.length) S.stats.forEach((s) => sel.append(h(\"option\", { value: s.key, text: s.label + (s.year ? \" \" + s.year : \"\") + ` (${s.nVehicles})` })));\n  sel.hidden = false;\n  const s = S.stats.find((x) => x.key === sel.value) || S.stats[0];\n  const dl = h(\"dl\", { class: \"kv\" }); const add = (k, v) => dl.append(h(\"dt\", { text: k }), h(\"dd\", { class: \"mono\", text: v }));\n  add(\"Motos enregistrées\", `${s.nVehicles}, dont ${s.nSold} vendue${s.nSold > 1 ? \"s\" : \"\"} et ${s.inStock} en stock`);\n  add(\"Achat moyen\", fcfa(s.avgPurchase)); add(\"Transport moyen\", fcfa(s.avgTransport)); add(\"Douane moyenne\", fcfa(s.avgCustoms)); add(\"Remise en état\", fcfa(s.avgPrep));\n  add(\"Prix de vente moyen\", s.nSold ? fcfa(s.avgSold) : \"aucune vente\"); add(\"Marge moyenne\", s.avgMargin != null ? fcfa(s.avgMargin) : \"—\"); add(\"Délai de vente\", s.avgDays != null ? s.avgDays + \" jours\" : \"—\");\n  box.append(dl, s.nSold < 5 ? h(\"div\", { class: \"note warn\", text: `Peu de données : ${s.nSold} vente${s.nSold > 1 ? \"s\" : \"\"}. À prendre comme un repère, pas comme une règle.` }) : null,\n    h(\"div\", {}, h(\"button\", { class: \"btn\", type: \"button\", text: \"Utiliser ces frais dans le calcul\", onclick: () => { calcMode = \"rapide\"; $(\"#c-approachU\").value = String(s.avgTransport + s.avgCustoms); $(\"#c-prepU\").value = String(s.avgPrep); if (s.nSold) $(\"#c-saleU\").value = String(s.avgSold); renderCalc(); toast(\"Frais et prix de vente moyens repris.\"); } })));\n}\n\n/* ---------- Navigation et démarrage ---------- */\nconst TABS = [\"agent\", \"fournisseurs\", \"calcul\", \"historique\"];\nfunction go(tab) { if (!TABS.includes(tab)) tab = \"agent\"; S.tab = tab; try { if (location.hash !== \"#\" + tab) location.hash = tab; } catch {} show(); }\nfunction show() {\n  for (const t of TABS) { $(\"#v-\" + t).hidden = t !== S.tab; $(\"#t-\" + t).setAttribute(\"aria-selected\", String(t === S.tab)); }\n  if (S.tab === \"agent\") renderAgent(); if (S.tab === \"fournisseurs\") renderSuppliers(); if (S.tab === \"historique\") renderHistory(); if (S.tab === \"calcul\") { renderCalc(); renderStats(); }\n}\nlet bootDone = false;\nasync function boot() {\n  for (const t of TABS) $(\"#t-\" + t).addEventListener(\"click\", () => go(t));\n  window.addEventListener(\"hashchange\", () => { const t = location.hash.slice(1); if (TABS.includes(t) && t !== S.tab) { S.tab = t; show(); } });\n  const ta = $(\"#ask\"); ta.addEventListener(\"input\", () => autoGrow(ta));\n  $(\"#send\").addEventListener(\"click\", send); $(\"#stop\").addEventListener(\"click\", () => S.ctl && S.ctl.abort());\n  $(\"#pick\").addEventListener(\"change\", (ev) => { S.images = [...ev.target.files].slice(0, 4); ev.target.value = \"\"; renderAgent(); });\n  $(\"#sheet-close\").addEventListener(\"click\", closeSheet);\n  $(\"#sup-add\").addEventListener(\"click\", () => { if (!cap.db) { toast(\"Enregistrement indisponible dans cette vue.\"); return; } openSheet({ kind: \"supplier\", id: null, mode: \"edit\" }); });\n  $(\"#sup-q\").addEventListener(\"input\", (ev) => { S.q = ev.target.value; renderSuppliers(); });\n  const saved = ls.get(\"achat-calc\", null);\n  if (saved && saved.v) { calcMode = saved.mode === \"detail\" ? \"detail\" : \"rapide\"; for (const id of CALC_IDS) if (saved.v[id] != null && $(\"#c-\" + id)) $(\"#c-\" + id).value = saved.v[id]; }\n  for (const id of CALC_IDS) { const el = $(\"#c-\" + id); el.addEventListener(\"input\", renderCalc); el.addEventListener(\"change\", renderCalc); }\n  $(\"#c-currency\").addEventListener(\"change\", () => { $(\"#c-rateShown\").value = \"\"; applyStoredRate(true); });\n  $(\"#c-rateShown\").addEventListener(\"change\", () => { const cur = $(\"#c-currency\").value, C = CURRENCIES[cur], v = num($(\"#c-rateShown\").value) / C.unit; if (!C.fixed && v > 0) saveRate(cur, v, today(), \"saisi par toi\").then(renderCalc); });\n  $(\"#m-rapide\").addEventListener(\"click\", () => { calcMode = \"rapide\"; renderCalc(); }); $(\"#m-detail\").addEventListener(\"click\", () => { calcMode = \"detail\"; renderCalc(); });\n  $(\"#rate-ask\").addEventListener(\"click\", (ev) => askRate(ev.currentTarget));\n  $(\"#c-model\").addEventListener(\"change\", renderStats);\n  $(\"#stats-load\").addEventListener(\"click\", async (ev) => { const b = ev.currentTarget; b.disabled = true; b.textContent = \"Lecture…\"; S.statsErr = \"\"; try { await loadStats(); } catch (e) { S.statsErr = e.message || \"Chiffres indisponibles.\"; } b.disabled = false; b.textContent = \"Charger mes chiffres réels\"; renderStats(); });\n  $(\"#calc-copy\").addEventListener(\"click\", (ev) => copy(calcText(), ev.currentTarget));\n  $(\"#calc-ask\").addEventListener(\"click\", () => { go(\"agent\"); const t = $(\"#ask\"); t.value = \"Donne-moi ton avis sur cette opération : est-elle rentable, quels postes vérifier, que négocier ?\\n\\n\" + calcText(); autoGrow(t); t.focus(); });\n  const h0 = location.hash.slice(1); S.tab = TABS.includes(h0) ? h0 : \"agent\"; show();\n\n  if (!window.claude || typeof window.claude.use !== \"function\") { bootDone = true; S.supState = \"off\"; $(\"#stats-load\").hidden = true; show(); return; }\n  const use = (n) => window.claude.use(n).catch(() => null);\n  const [sample, db, mcp] = await Promise.all([use(\"sample\"), use(\"db\"), use(\"mcp\")]);\n  cap.sample = sample; cap.db = db; cap.mcp = mcp;\n  if (sample) { const lim = await sample.limits().catch(() => null); cap.tools = !!(lim && lim.tools); cap.images = !!(lim && lim.images); }\n  if (mcp) {\n    const lt = await mcp.listTools().catch(() => null);\n    const names = lt && lt.servers ? lt.servers.filter((s) => s.kind !== \"artifact\" && s.authStatus !== \"needs_reauth\").map((s) => s.server) : null;\n    cap.web = cap.tools && (!names || names.includes(SRV_WEB)); cap.soft = !names || names.includes(SRV_CF);\n  }\n  cap.soft = !!cap.soft; cap.web = !!cap.web;\n  $(\"#stats-load\").hidden = !cap.soft;\n  if (SA) { try { S.saKey = !!(await api(\"status\")).key; } catch { S.saKey = null; } }\n  bootDone = true; subscribe(); show();\n}\nboot();\n\n})();\n</script>\n</body>\n</html>\n";
